import{_ as e,o as r,c as o,a}from"./chunks/plugin-vue_export-helper.F1EaaLXR.js";const d=JSON.parse('{"title":"Проект-пингвин","description":"","frontmatter":{"site":"pro","title":"Проект-пингвин","date":"2026-11-08T00:00:00.000Z","source":"https://t.me/jfyi_ps/129","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-11-08-proekt-pingvin"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Проект-пингвин"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-11-08-proekt-pingvin"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Проект-пингвин"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Проект-пингвин\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-11-08-proekt-pingvin\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-11-08\\"}"]]},"headers":[],"relativePath":"posts/2026-11-08-proekt-pingvin.md","filePath":"posts/2026-11-08-proekt-pingvin.md"}'),p={name:"posts/2026-11-08-proekt-pingvin.md"};function i(n,t,s,g,c,l){return r(),o("div",null,[...t[0]||(t[0]=[a('<p>Сейчас оценка любой по сложности задачи сводится к 120 минутам работы. Это время необходимо чтобы сформулировать план, обновить архитектуру и дождаться работы агентов.</p><p>Но код никогда не был узким местом в разработке.</p><p>Разработку сейчас принято делить на две фазы - Discovery и Delivery.</p><p>Delivery вдоль и поперёк покрыт метриками - DORA, Lead Time, CFR, MTTR, Flow Efficiency и др. От них зависят премии и все изменения процессов должны их улучшать.Тестирование и сопровождение тоже входит в Delivery.</p><p>Discovery же может затянуться на год. Согласующий директор в отпуске, консультации с командой разработки требуют их сильного переключения контекста и влияет на качество гипотез, отсутствуют метрики воронки продаж, таймбоксинг генерации идей, процесс не выстроен, много сложных смежников и тд. В итоге работа приходит в движение только по пинку инвестора и в результате все плюют на DoR чтобы делать хоть что-то.</p><p>Знакомая ситуация? В Jira есть Накопительная диаграмма потока (Cumulative Flow Diagram). Если у вас три месяца тишина, а под конец квартала резко появляются и закрываются сотни задач - у вас <strong>проект-пингвин</strong>.</p><p>Я бы не был собой, если бы не решал подобные проблемы инженерными методами.</p><p><strong>Первое.</strong> Для улучшения качества исследований, ИИ нужно скормить весь контекст проекта, вместе с кодом, письмами и чатами.</p><p>Чтобы люди, занятые Discovery не отвлекали людей, занятых в Delivery, я сделал KB (knowledge boss - <a href="https://setka.ru/redirect?to=https%3A%2F%2Fgithub.com%2Falterfo%2Fkb" target="_blank" rel="noreferrer">https://setka.ru/redirect?to=https%3A%2F%2Fgithub.com%2Falterfo%2Fkb</a>). Работая на GPU домашнего уровня с локальными моделями заняла первое место в русскоязычном RAG Leaderbord DRAGON (<a href="https://setka.ru/redirect?to=https%3A%2F%2Fhuggingface.co%2Fspaces%2Fai-forever%2Frag-leaderboard" target="_blank" rel="noreferrer">https://setka.ru/redirect?to=https%3A%2F%2Fhuggingface.co%2Fspaces%2Fai-forever%2Frag-leaderboard</a>)</p><p>Если на вашем проекте очень много кода, документации, вся актуальная инфа в чатах, а доки устарели - это решение для вас.</p><p><strong>Второе.</strong> Написать инструментарий стало проще, чем найти подходящий. Это приватнее, безопаснее, и удобнее. Мой набор инструментов (трекер решений, редактор диаграмм IDEF0, журнал для записи мыслей, финансовый трекер) лежит тут <a href="https://setka.ru/redirect?to=https%3A%2F%2Falterfo.github.io%2F" target="_blank" rel="noreferrer">https://setka.ru/redirect?to=https%3A%2F%2Falterfo.github.io%2F</a>. Я пользуюсь каждым из них минимум раз в день и дорабатываю под свои нужды. Открыв инструмент вы получаете полную его копию локально. Синхронизация по локальной сети через WebRTC по куаркоду реализована в некоторых из них. Доработать для общей работы - дело 120 минут если понадобится.</p><p><strong>Десерт.</strong> Если у вас есть набор автотестов, их можно легко превратить в робота-автопилота, который ходит по вашему приложению как пользователь и иногда заходить туда, куда ваш e2e ещё не написан. Инфраструктура для обучения таких автопилотов лежит в игре, которую я писал на заре внедрения вайбкодинга в энтерпрайз чтобы обкатать то, о чем пишу: <a href="https://setka.ru/redirect?to=https%3A%2F%2Fgithub.com%2Falterfo%2Fvacuum-rogues" target="_blank" rel="noreferrer">https://setka.ru/redirect?to=https%3A%2F%2Fgithub.com%2Falterfo%2Fvacuum-rogues</a></p><p>Обращайтесь за помощью внедрения подобных технологий в ваш AISDLC. Буду рад быть полезен.</p>',13)])])}const h=e(p,[["render",i]]);export{d as __pageData,h as default};
